#include "TestSupport.h"
#include "../src/Shop/ShopPresentationState.h"
#include <variant>
int main(){ TestContext t; ShopPresentationState s; ShopOpenedEvent e{4,1,NpcType::DEVELOPMENT_GUIDE,77,ShopId::DEVELOPMENT_GUIDE_SUPPLIES,"Supplies",ItemType::COINS,{{ItemType::COOKED_MEAT,8,3}}}; ActiveShopSession a{77,4,1,NpcType::DEVELOPMENT_GUIDE,ShopId::DEVELOPMENT_GUIDE_SUPPLIES,1}; s.Synchronize(4,{e},&a); t.Expect(s.IsOpen(),"Matching identity opens shop"); auto b=s.MakeBuy(0); auto* buy=b?std::get_if<ShopBuyCommand>(&*b):nullptr; t.Expect(buy&&buy->shopSessionId==77&&buy->itemType==ItemType::COOKED_MEAT,"Buy preserves identity"); s.ReconcileRejectedCommand(); s.Synchronize(4,{},&a); t.Expect(s.HasRejection(),"No-event synchronization preserves rejection feedback"); s.Synchronize(4,{e},&a); t.Expect(!s.HasRejection(),"Authoritative replacement clears rejection feedback"); ActiveShopSession mismatch=a; mismatch.npcEntityID=9; s.ReconcileRejectedCommand(); s.Synchronize(4,{e},&mismatch); t.Expect(!s.IsOpen()&&!s.HasRejection(),"NPC mismatch clears shop and feedback"); s.Synchronize(4,{e},&a); ShopOpenedEvent bad=e; bad.sessionId=78; s.ReconcileRejectedCommand(); s.Synchronize(4,{bad},&a); t.Expect(!s.IsOpen()&&!s.HasRejection(),"Session mismatch clears shop and feedback"); s.Synchronize(4,{e},&a); s.Dismiss(); s.Synchronize(4,{e},&a); t.Expect(!s.IsOpen()&&!s.HasRejection(),"Dismissed session stays closed without feedback"); s.Synchronize(4,{},nullptr); t.Expect(!s.MakeSell(0).has_value()&&!s.MakeClose().has_value(),"Stale commands are rejected"); return t.Finish(); }
